def CuspEmbedding.weaken {W : CompactCarrier.{u}}
    {g : SmoothRiemannianMetric W.model W.Carrier} {K : ℕ} {δ₁ δ₂ : ℝ}
    {X : Set W.Carrier} (e : CuspEmbedding W g K δ₁ X) (hδ : δ₁ ≤ δ₂) :
